from collect import group_by

def test_group_calls_independent():
    a = group_by([1, 2], lambda x: x % 2)
    b = group_by([10], lambda x: x % 2)
    assert a == {1: [1], 0: [2]}
    assert b == {0: [10]}

def test_group_empty():
    assert group_by([], lambda x: x) == {}


from recursion import count_nodes

def test_count_nested():
    assert count_nodes({"a": {"b": {}}}) == 3

def test_count_empty():
    assert count_nodes({}) == 1

def test_count_scalar():
    assert count_nodes(5) == 0
